sql.where:
DEL_FLAG = '0'

    AND ENTERPRISE_ID = #{queryVo.enterpriseId}


    AND ENTERPRISE_NAME LIKE CONCAT('%', #{queryVo.enterpriseName}, '%')


    AND TASK_NAME LIKE CONCAT('%', #{queryVo.taskName}, '%')


    AND TASK_TYPE = #{queryVo.taskType}


    AND SUBMISSION_TYPE = #{queryVo.submissionType}


    AND REGULATORY_DEPARTMENT = #{queryVo.regulatoryDepartment}


    AND TASK_SOURCE = #{queryVo.taskSource}


    AND PRIORITY = #{queryVo.priority}


    AND TASK_STATUS = #{queryVo.taskStatus}


    AND RESPONSIBLE_PERSON LIKE CONCAT('%', #{queryVo.responsiblePerson}, '%')


    AND RESPONSIBLE_DEPARTMENT LIKE CONCAT('%', #{queryVo.responsibleDepartment}, '%')


    AND FEEDBACK_STATUS = #{queryVo.feedbackStatus}


    AND PLANNED_START_TIME >= #{queryVo.plannedStartTimeBegin}


    AND PLANNED_START_TIME <= #{queryVo.plannedStartTimeEnd}


    AND PLANNED_END_TIME >= #{queryVo.plannedEndTimeBegin}


    AND PLANNED_END_TIME <= #{queryVo.plannedEndTimeEnd}


    AND DEADLINE >= #{queryVo.deadlineBegin}


    AND DEADLINE <= #{queryVo.deadlineEnd}


    AND CREATE_TIME >= #{queryVo.createTimeBegin}


    AND CREATE_TIME <= #{queryVo.createTimeEnd}


    AND COMPLETION_PROGRESS >= #{queryVo.progressMin}


    AND COMPLETION_PROGRESS <= #{queryVo.progressMax}


    AND QUALITY_SCORE >= #{queryVo.qualityScoreMin}


    AND QUALITY_SCORE <= #{queryVo.qualityScoreMax}


    AND DEADLINE < NOW() AND TASK_STATUS != '已完成'

mapper.update:
UPDATE DATA_SUBMISSION_TASK SET TASK_STATUS = #{status}, UPDATE_BY = #{updateBy}, UPDATE_TIME = NOW() WHERE TASK_ID IN
#{taskId}
AND DEL_FLAG = '0'

UPDATE DATA_SUBMISSION_TASK SET DEL_FLAG = '1', UPDATE_BY = #{updateBy}, UPDATE_TIME = NOW() WHERE TASK_ID IN
#{taskId}
AND DEL_FLAG = '0'
